def scene(id, title, speaker, statement, question, options, correct, explanation, takeaway, label, source, changed=None):
    result = dict(id=id, scene=title, speaker=speaker, statement=statement, question=question, options=options, correct=correct, explanation=explanation, takeaway=takeaway, legalLabel=label, sourceUrl=source[0], sourceLabel=source[1])
    if changed:
        result['changed'] = changed
    return result

def pair(base, twist):
    base['twist'] = twist
    return base

